-- ============================================================
-- Manual SQL — pieces not generated by prisma migrate diff
-- (CHECK constraints, plpgsql triggers, partial / functional indexes)
-- ============================================================


-- ------------------------------------------------------------
-- 1. CHECK constraints (Prisma does not model CHECK)
-- ------------------------------------------------------------

ALTER TABLE "estabelecimento"
    ADD CONSTRAINT "ck_estab_nota"
    CHECK (nota_media >= 0.00 AND nota_media <= 5.00);

ALTER TABLE "produto"
    ADD CONSTRAINT "ck_produto_preco"
    CHECK (preco_regular > 0);

ALTER TABLE "anuncio"
    ADD CONSTRAINT "ck_anuncio_preco"
    CHECK (preco_promocional > 0);
ALTER TABLE "anuncio"
    ADD CONSTRAINT "ck_anuncio_quantidade_inicial"
    CHECK (quantidade_inicial > 0);
ALTER TABLE "anuncio"
    ADD CONSTRAINT "ck_anuncio_quantidade_disponivel"
    CHECK (quantidade_disponivel >= 0);
ALTER TABLE "anuncio"
    ADD CONSTRAINT "ck_anuncio_quantidade_sobra"
    CHECK (quantidade_sobra >= 0);
ALTER TABLE "anuncio"
    ADD CONSTRAINT "ck_anuncio_prazo"
    CHECK (prazo_retirada > data_publicacao);

ALTER TABLE "pedido"
    ADD CONSTRAINT "ck_pedido_valor"
    CHECK (valor_total > 0);
ALTER TABLE "pedido"
    ADD CONSTRAINT "ck_pedido_taxa_comissao"
    CHECK (taxa_comissao >= 0 AND taxa_comissao <= 100);
ALTER TABLE "pedido"
    ADD CONSTRAINT "ck_pedido_valor_comissao"
    CHECK (valor_comissao >= 0);
ALTER TABLE "pedido"
    ADD CONSTRAINT "ck_pedido_cancelamento"
    CHECK (
        (status = 'CANCELADO' AND cancelado_por IS NOT NULL AND data_cancelamento IS NOT NULL)
        OR status != 'CANCELADO'
    );

ALTER TABLE "item_pedido"
    ADD CONSTRAINT "ck_item_quantidade"
    CHECK (quantidade > 0);
ALTER TABLE "item_pedido"
    ADD CONSTRAINT "ck_item_preco"
    CHECK (preco_unitario > 0);

ALTER TABLE "pagamento"
    ADD CONSTRAINT "ck_pagamento_valor"
    CHECK (valor > 0);

ALTER TABLE "avaliacao"
    ADD CONSTRAINT "ck_avaliacao_nota"
    CHECK (nota BETWEEN 1 AND 5);

ALTER TABLE "device_token"
    ADD CONSTRAINT "ck_device_plataforma"
    CHECK (plataforma IN ('android', 'ios'));


-- ------------------------------------------------------------
-- 2. Trigger: keep estabelecimento.nota_media in sync with avaliacao
-- ------------------------------------------------------------

CREATE OR REPLACE FUNCTION fn_atualizar_nota_media()
RETURNS TRIGGER AS $$
DECLARE
    v_id_estabelecimento BIGINT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        v_id_estabelecimento := OLD.id_estabelecimento;
    ELSE
        v_id_estabelecimento := NEW.id_estabelecimento;
    END IF;

    UPDATE estabelecimento
    SET    nota_media = (
        SELECT COALESCE(AVG(nota), 0)
        FROM   avaliacao
        WHERE  id_estabelecimento = v_id_estabelecimento
    )
    WHERE id = v_id_estabelecimento;

    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_nota_media
AFTER INSERT OR UPDATE OR DELETE ON avaliacao
FOR EACH ROW EXECUTE FUNCTION fn_atualizar_nota_media();


-- ------------------------------------------------------------
-- 3. Trigger: restock anuncio when a pedido is cancelled
-- ------------------------------------------------------------

CREATE OR REPLACE FUNCTION fn_controle_estoque()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.status = 'CANCELADO' AND OLD.status != 'CANCELADO' THEN
        UPDATE anuncio a
        SET    quantidade_disponivel = a.quantidade_disponivel + ip.quantidade
        FROM   item_pedido ip
        WHERE  ip.id_pedido = NEW.id
          AND  ip.id_anuncio = a.id;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_controle_estoque
AFTER UPDATE ON pedido
FOR EACH ROW EXECUTE FUNCTION fn_controle_estoque();


-- ------------------------------------------------------------
-- 4. Geospatial / partial indexes
-- ------------------------------------------------------------

CREATE INDEX IF NOT EXISTS idx_endereco_lat_lng
    ON endereco (latitude, longitude);

CREATE INDEX IF NOT EXISTS idx_anuncio_status_prazo
    ON anuncio (status, prazo_retirada)
    WHERE status = 'ATIVO';
